/**
 * GameEngine - Centralized game loop and state management
 * Handles frame timing, delta time calculation, and state transitions
 */
export class GameEngine {
  constructor() {
    this.running = false;
    this.paused = false;
    this.gameState = 'menu'; // menu | playing | paused | gameOver | victory
    this.lastTime = 0;
    this.accumulatedTime = 0;
    this.fixedDelta = 1 / 60;
    this.maxAccumulation = 3 * this.fixedDelta;
    this.frameCount = 0;

    // Input state (populated by InputHandler)
    this.inputs = {};

    // VFX system references (set by game-specific code)
    this.cameraShake = null;
    this.hitStop = null;
    this.particleSystem = null;
    this.trailManager = null;

    // Game systems callbacks
    this._updateCallbacks = [];
    this._renderCallbacks = [];
    this._stateChangeCallbacks = [];
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.accumulatedTime = 0;
    this.frameCount = 0;
    requestAnimationFrame(this._loop.bind(this));
  }

  stop() {
    this.running = false;
    if (this._rafId) cancelAnimationFrame(this._rafId);
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    this.lastTime = performance.now();
    requestAnimationFrame(this._loop.bind(this));
  }

  setState(newState) {
    const oldState = this.gameState;
    this.gameState = newState;

    if (newState === 'playing') {
      this.running = true;
      this.paused = false;
      this.lastTime = performance.now();
      this.accumulatedTime = 0;
      requestAnimationFrame(this._loop.bind(this));
    } else if (newState === 'paused' && this.running) {
      this.paused = true;
    } else if (newState === 'menu') {
      this.running = false;
      this.paused = false;
    }

    // Emit state change event for game-specific handling
    const onGameStateChange = this._stateChangeCallbacks || (() => {});
    onGameStateChange(oldState, newState);
  }

  getDeltaTime() {
    return this.accumulatedTime / (this.frameCount + 1) || this.fixedDelta;
  }

  _loop(timestamp) {
    if (!this.running) return;

    const deltaTime = timestamp - this.lastTime;
    this.lastTime = timestamp;

    // Cap delta time to prevent spiral of death
    if (deltaTime > 0.1) {
      this.accumulatedTime += this.fixedDelta;
      this.frameCount++;
      this._update(this.fixedDelta);
      return;
    }

    this.accumulatedTime += deltaTime;
    this.frameCount++;

    while (this.accumulatedTime >= this.fixedDelta) {
      this.accumulatedTime -= this.fixedDelta;
      this._update(this.fixedDelta);
    }

    // Render every frame regardless of physics step
    this._render();
  }

  _update(deltaTime) {
    if (this.paused || !this.running) return;

    // Apply hit-stop time dilation
    let effectiveDelta = deltaTime;
    if (this.hitStop && this.hitStop.active) {
      effectiveDelta *= this.hitStop.scaleFactor;
    }

    // Update game systems
    const onUpdate = this._updateCallbacks || (() => {});
    onUpdate(effectiveDelta);

    // Update VFX systems
    if (this.cameraShake && this.cameraShake.update(deltaTime)) {
      this.cameraShake.active = true;
    } else {
      this.cameraShake.active = false;
    }

    if (this.particleSystem) {
      this.particleSystem.update(deltaTime);
    }

    // Update trails
    if (this.trailManager) {
      this.trailManager.update(deltaTime);
    }
  }

  _render() {
    const onRender = this._renderCallbacks || (() => {});
    onRender();
  }

  registerUpdate(callback) {
    this._updateCallbacks.push(callback);
  }

  registerRender(callback) {
    this._renderCallbacks.push(callback);
  }

  registerStateChange(handler) {
    this._stateChangeCallbacks.push(handler);
  }
}

export default GameEngine;
