/**
 * CameraShake - Trauma-based camera shake system with decaying intensity.
 * Scales shake magnitude by impact velocity to create realistic trauma effects.
 */

class CameraShake {
  constructor() {
    this.active = false;
    this.intensity = 0;
    this.decayRate = 12.0; // How fast the shake decays per second
    this.minIntensity = 0.5; // Minimum visible shake amount
    this.maxDuration = 3.0; // Maximum duration in seconds

    // Track impact history for cumulative effect
    this.impactHistory = [];
    this._lastImpactTime = 0;
  }

  /**
   * Trigger a camera shake based on impact velocity.
   * Higher impact velocity = more intense shake.
   */
  trigger(velocity) {
    const now = performance.now();
    const timeSinceLast = (now - this._lastImpactTime) / 1000;

    // Decay previous impacts over time
    if (timeSinceLast < 0.5) {
      // Cumulative impact: add to current intensity
      this.intensity += velocity * 0.3;
    } else {
      // New independent impact
      this.intensity = Math.max(this.intensity, velocity * 0.3);
    }

    this._lastImpactTime = now;
    this.active = true;
  }

  /**
   * Update camera shake for one frame. Returns false when inactive.
   */
  update(deltaTime) {
    if (!this.active || this.intensity <= this.minIntensity) {
      this.active = false;
      return false;
    }

    // Decay intensity exponentially
    const decayFactor = Math.pow(0.9, deltaTime * this.decayRate);
    this.intensity *= decayFactor;

    // Clamp to minimum visible value while still decaying
    if (this.intensity > this.minIntensity) {
      this.intensity -= deltaTime * 2;
    } else {
      this.active = false;
    }

    return true;
  }

  /**
   * Get the current shake offset as a [x, y] array.
   */
  getOffset() {
    if (!this.active || this.intensity <= this.minIntensity) {
      return [0, 0];
    }

    // Use sine waves for organic-looking shake
    const time = performance.now() * 0.1;
    const x = (Math.sin(time * 3) + Math.cos(time * 5)) * this.intensity;
    const y = (Math.cos(time * 2) - Math.sin(time * 4)) * this.intensity;

    return [x, y];
  }

  /**
   * Get current intensity for UI display.
   */
  getIntensity() {
    return this.intensity;
  }

  /**
   * Reset camera shake to inactive state.
   */
  reset() {
    this.active = false;
    this.intensity = 0;
    this.impactHistory = [];
  }
}

