/**
 * MotionTrail - Trail buffer for fast-moving objects.
 * Stores previous positions and renders them as fading particles/lines.
 */

class MotionTrail {
  constructor() {
    this.trails = new Map(); // key: object ID -> trail data
    this.maxTrailLength = 20; // Maximum number of positions to store per trail
    this.fadeSpeed = 5.0; // How quickly trail fades (per second)

    // Trail rendering buffer (Three.js geometry for efficient rendering)
    this.trailGeometry = null;
    this.trailBuffer = null;
    this.trailMaterial = null;
    this._trailMesh = null;
  }

  /**
   * Initialize the trail system with Three.js mesh and material.
   */
  init(scene, camera) {
    // Create a line geometry for rendering trails as lines
    const positions = new Float32Array(0);
    this.trailGeometry = new THREE.BufferGeometry();
    this.trailGeometry.setPositions(positions);

    // Create trail material with transparency and glow
    this.trailMaterial = new THREE.MeshStandardMaterial({
      color: 0x4488ff,
      transparent: true,
      opacity: 0.6,
      size: 2,
      side: THREE.DoubleSide
    });

    // Create trail mesh (hidden until needed)
    this._trailMesh = new THREE.LineSegments(this.trailGeometry, this.trailMaterial);
    this._trailMesh.visible = false;
    scene.add(this._trailMesh);

    // Set initial position for camera-relative rendering
    this._cameraPos = camera.position.clone();
  }

  /**
   * Start tracking a moving object. Returns a trail ID.
   */
  startTracking(object, id) {
    if (!this.trails.has(id)) {
      this.trails.set(id, {
        positions: [],
        maxLength: this.maxTrailLength,
        startTime: performance.now()
      });
    }

    // Add initial position
    const pos = [object.position.x, object.position.y, object.position.z];
    this.trails.get(id).positions.push(...pos);
  }

  /**
   * Update trail for a moving object. Adds new position and removes old ones.
   */
  update(object, id) {
    const trail = this.trails.get(id);
    if (!trail) return;

    // Add current position
    const pos = [object.position.x, object.position.y, object.position.z];
    trail.positions.push(...pos);

    // Trim to max length
    while (trail.positions.length > trail.maxLength * 3) {
      trail.positions.splice(0, 1);
    }

    // Update Three.js geometry with current positions
    this._updateGeometry(trail);
  }

  /**
   * Stop tracking an object. Removes its trail data and disposes resources.
   */
  stopTracking(id) {
    const trail = this.trails.get(id);
    if (trail) {
      // Dispose of any stored geometries
      if (typeof trail.geometry.dispose === 'function') {
        trail.geometry.dispose();
      }
      this.trails.delete(id);
    }
  }

  /**
   * Update the Three.js geometry with all current trail positions.
   */
  _updateGeometry(trail) {
    if (trail.positions.length < 2) return;

    const positions = new Float32Array(trail.positions.length * 3);
    for (let i = 0; i < trail.positions.length; i++) {
      positions[i * 3] = trail.positions[i * 3];
      positions[i * 3 + 1] = trail.positions[i * 3 + 1];
      positions[i * 3 + 2] = trail.positions[i * 3 + 2];
    }

    this.trailGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  }

  /**
   * Get all active trail IDs.
   */
  getActiveIds() {
    return Array.from(this.trails.keys());
  }

  /**
   * Clear all trails and dispose resources.
   */
  clear() {
    for (const id of this.trails.keys()) {
      this.stopTracking(id);
    }
    this.trails.clear();

    if (this._trailMesh) {
      this._trailMesh.visible = false;
    }
  }

  /**
   * Get trail data for a specific ID.
   */
  getTrail(id) {
    return this.trails.get(id);
  }
}

export default MotionTrail;
