 * Creates expanding circles that fade over time.
 */

class Shockwave {
  constructor(scene) {
    this.scene = scene;
    this.activeRings = []; // Array of active shockwave rings
    this._ringGeometry = null;
    this._ringMaterial = null;
    this._ringMesh = null;
  }

  /**
   * Initialize the shockwave system with Three.js mesh and material.
   */
  init() {
    // Create a ring geometry (circle)
    const radius = 10;
    const segments = 64;
    this._ringGeometry = new THREE.TorusGeometry(0.5, radius, segments);

    // Create glow material for shockwave effect
    this._ringMaterial = new THREE.MeshStandardMaterial({
      color: 0x44ffaa,
      transparent: true,
      opacity: 1.0,
      size: 2,
      side: THREE.DoubleSide
    });

    // Create ring mesh (hidden until needed)
    this._ringMesh = new THREE.Mesh(this._ringGeometry, this._ringMaterial);
    this._ringMesh.visible = false;
    this.scene.add(this._ringMesh);
  }

  /**
   * Spawn a shockwave ring at the given position.
   */
  spawn(x, y, z) {
    const now = performance.now();

    // Create a new ring mesh for each shockwave
    const geometry = new THREE.TorusGeometry(0.3, 5, 64);
    const material = new THREE.MeshStandardMaterial({
      color: 0x44ffaa,
      transparent: true,
      opacity: 1.0,
      size: 2,
      side: THREE.DoubleSide
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(x, y, z);
    this.scene.add(mesh);

    // Store ring data for cleanup
    const ringData = {
      mesh,
      geometry,
      material,
      startTime: now,
      duration: 1.0, // Shockwave lasts 1 second
      maxRadius: 5,
      speed: 20, // Expansion speed in units per second
      alpha: 1.0
    };

    this.activeRings.push(ringData);
  }

  /**
   * Update all active shockwaves for one frame.
   */
  update(deltaTime) {
    const now = performance.now();

    // Remove expired rings and update remaining ones
    for (let i = this.activeRings.length - 1; i >= 0; i--) {
      const ring = this.activeRings[i];
      const elapsed = (now - ring.startTime) / 1000;

      if (elapsed >= ring.duration) {
        // Remove expired ring
        this.scene.remove(ring.mesh);
        ring.geometry.dispose();
        ring.material.dispose();
        this.activeRings.splice(i, 1);
      } else {
        // Expand the ring
        const progress = elapsed / ring.duration;
        const expandedRadius = ring.maxRadius * progress;

        // Update geometry radius (in-place modification)
        const positions = ring.geometry.attributes.position.array;
        for (let j = 0; j < positions.length; j += 3) {
          positions[j] *= Math.sqrt(progress);
          positions[j + 1] *= Math.sqrt(progress);
        }

        // Fade out alpha over time
        ring.alpha = 1.0 - progress;
        ring.material.opacity = ring.alpha;
      }
    }
  }

  /**
   * Get count of active shockwaves.
   */
  get size() {
    return this.activeRings.length;
  }

  /**
   * Clear all shockwaves and dispose resources.
   */
  clear() {
    for (const ring of this.activeRings) {
      this.scene.remove(ring.mesh);
      ring.geometry.dispose();
      ring.material.dispose();
    }
    this.activeRings = [];

    if (this._ringMesh) {
      this.scene.remove(this._ringMesh);
    }
  }
}

export default Shockwave;
