import { EffectComposer, RenderPass } from 'three/addons/postprocessing/EffectComposer.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { AmbientBlurPass } from 'three/addons/postprocessing/AmbientBlurPass.js';
import { ColorCorrectionPass } from 'three/addons/post-processing/ColorCorrectionPass.js';
import { VignettePass } from 'three/addons/post-processing/VignettePass.js';

class EffectComposerWrapper {
  constructor(scene, camera) {
    this.composer = new EffectComposer(renderer);
    this.bloomPass = null;
    this.ambientBlur = null;
    this.colorCorrection = null;
    this.vignette = null;
    this.renderer = renderer;

    // Build post-processing chain
    const clearColor = 0x050510; // Deep space black
    this.composer.addPass(new RenderPass(scene, camera));

    // Ambient blur for subtle glow around bright objects
    this.ambientBlur = new AmbientBlurPass();
    this.composer.addPass(this.ambientBlur);

    // Unreal bloom pass for neon glow effect
    this.bloomPass = new UnrealBloomPass(0x000000, 0.6, 0.4, 0.8);
    this.composer.addPass(this.bloomPass);

    // Color correction for retro CRT feel (slight blue tint)
    this.colorCorrection = new ColorCorrectionPass({
      gamma: 1.2,
      contrast: 1.1,
      saturation: 0.95
    });
    this.composer.addPass(this.colorCorrection);

    // Vignette for CRT edge darkening
    this.vignette = new VignettePass({ radius: 0.7 });
    this.composer.addPass(this.vignette);

    // Add post-processing group to scene
    const postProcessGroup = new THREE.Group();
    scene.add(postProcessGroup);
  }

  render() {
    this.composer.render();
  }

  getComposer() {
    return this.composer;
  }

  getBloomPass() {
    return this.bloomPass;
  }

  setBloomThreshold(threshold) {
    if (this.bloomPass) {
      this.bloomPass.threshold = threshold;
    }
  }

  setBloomRadius(radius) {
    if (this.bloomPass) {
      this.bloomPass.radius = radius;
    }
  }

  setBloomContrast(contrast) {
    if (this.bloomPass) {
      this.bloomPass.contrast = contrast;
    }
  }

  setBloomExposure(exposure) {
    if (this.bloomPass) {
      this.bloomPass.exposure = exposure;
    }
  }
}

export default EffectComposerWrapper;
