/**
 * UnrealBloomPass - Custom bloom pass configuration for neon glow effect.
 * Provides fine-grained control over the bloom parameters used in post-processing.
 */

import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

class CustomUnrealBloomPass extends UnrealBloomPass {
  constructor(threshold = 0.3, radius = 2.0, contrast = 1.5, exposure = 0.8) {
    super(threshold, radius, contrast, exposure);

    // Configure the bloom texture for better neon glow
    this.bloomTexture = new THREE.CanvasTexture(256, 256);
    const ctx = this.bloomTexture.getContext('2d');
    const gradient = ctx.createRadialGradient(0.5, 0.5, 0, 0.5, 0.5, 1);
    gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, 256, 256);

    // Set up the bloom pass with custom parameters
    this.threshold = threshold;
    this.radius = radius;
    this.contrast = contrast;
    this.exposure = exposure;
  }

  /**
   * Configure the bloom pass with specific parameters.
   */
  setThreshold(threshold) {
    this.threshold = Math.max(0, Math.min(1, threshold));
  }

  setRadius(radius) {
    this.radius = Math.max(0.5, radius);
  }

  setContrast(contrast) {
    this.contrast = Math.max(0.5, contrast);
  }

  setExposure(exposure) {
    this.exposure = Math.max(0.1, exposure);
  }
}

export default CustomUnrealBloomPass;
